#include <bits/stdc++.h>
#define append push_back
#define X first
#define Y second
#define LL long long
#define read_array(a,n) for(int i=0;i<n;i++)cin>>a[i]
using namespace std;

template <class T, class L> T& maximize(T &x, L y){if(y>x)x=y;return x;}
template <class T, class L> T& minimize(T &x, L y){if(y<x)x=y;return x;}
typedef pair<LL,LL> pair_ll;
const int MAXN=200017;
unordered_map<LL,LL> memo_map;
LL count_digits(LL x){
  LL cnt=0;
  while(x){
    cnt++;
    x/=10;
  }
  return cnt;
}
LL reverse_num(LL x){
  LL digits[17],pos=0;
  while(x){
    digits[pos++]=(x%10)-(x<0?-1:1);
    x/=10;
  }
  LL res=0;
  while(pos--){
    res=res*10+digits[pos];
  }
  return res;
}
LL previous_value(LL x){
  LL c=0,orig=x;
  while(x){
    c*=10;
    c+=(x<0?-1:1);
    x/=10;
  }
  c*=10;
  c++;
  return orig - c;
}
LL last_digit(LL x){
  while(x>=10)
    x/=10;
  return x;
}
LL delete_leading(LL x){
  LL digits[17],p=0;
  while(x>=10){
    digits[p++]=x%10;
    x/=10;
  }
  LL res=0;
  while(p--){
    res=res*10+digits[p];
  }
  return res;
}
LL solve(LL x){
  if(x<=11)return min(13 - x, x);
  if(memo_map[x])return memo_map[x];
  LL n=0,t=1;
  while(t<x){
    t*=10;
    t++;
    n++;
  }
  if(x*2>=t)
    return memo_map[x]=min(solve(t - x)+n+1, (x/(t/10))*n+solve(x%(t/10)));
  return memo_map[x]=(x/(t/10))*n+solve(x%(t/10));
}

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  LL a;
  cin>>a;
  cout<<solve(a)<<'\n';
  return 0;
}
